using namespace std;

class Solution {
    int find(int x, vector<int>& parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }
    void unite(int x, int y, vector<int>& parent) {
        int rx = find(x, parent), ry = find(y, parent);
        if (rx != ry) parent[rx] = ry;
    }

public:
    int minimumHammingDistance(vector<int>& source, vector<int>& target, vector<vector<int>>& allowedSwaps) {
        int n = source.size();
        vector<int> parent(n);
        for (int i = 0; i < n; ++i) parent[i] = i;
        for (const auto& e : allowedSwaps) {
            unite(e[0], e[1], parent);
        }
        unordered_map<int, vector<int>> comps;
        for (int i = 0; i < n; ++i) {
            comps[find(i, parent)].push_back(i);
        }
        int diff = 0;
        for (const auto& [root, indices] : comps) {
            unordered_map<int, int> freq;
            for (int idx : indices) freq[source[idx]]++;
            for (int idx : indices) {
                int val = target[idx];
                if (freq[val] > 0) {
                    freq[val]--;
                } else {
                    diff++;
                }
            }
        }
        return diff;
    }
};

import java.util.*;

class Solution {
    private int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private void union(int x, int y, int[] parent) {
        int rx = find(x, parent), ry = find(y, parent);
        if (rx != ry) parent[rx] = ry;
    }

    public int minimumHammingDistance(int[] source, int[] target, int[][] allowedSwaps) {
        int n = source.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;
        for (int[] e : allowedSwaps) {
            union(e[0], e[1], parent);
        }
        Map<Integer, List<Integer>> comps = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            int root = find(i, parent);
            comps.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
        }
        int diff = 0;
        for (List<Integer> indices : comps.values()) {
            Map<Integer, Integer> freq = new HashMap<>();
            for (int idx : indices) {
                freq.put(source[idx], freq.getOrDefault(source[idx], 0) + 1);
            }
            for (int idx : indices) {
                int val = target[idx];
                int count = freq.getOrDefault(val, 0);
                if (count > 0) {
                    freq.put(val, count - 1);
                } else {
                    diff++;
                }
            }
        }
        return diff;
    }
}

